"use client";

import { useMutation } from "@tanstack/react-query";
import { api } from "@/lib/api/client";
import { downloadReportCsv, reconcileCampaign } from "@/lib/api/flows";

/** Screen 7: the backend checks every confirmed payout, ledger entry and open balance on Stellar (can take seconds). */
export function useReconcile(campaign: string | undefined) {
	return useMutation({ mutationFn: () => reconcileCampaign(api, campaign!) });
}

/** The organization CSV, generated by the backend (allocation references only, never names). */
export function useDownloadReport(campaign: string | undefined) {
	return useMutation({ mutationFn: (fallbackName: string) => downloadReportCsv(api, campaign!, fallbackName) });
}
